import {generateDemo,renderMix,peaksFor} from './audio-core.mjs';
const demos=new Map();
self.onmessage=({data})=>{try{const {id,version,assets}=data;const sr=version.sampleRate||22050,demoKey=version.direction+':'+sr;let sources={};if(version.source==='demo'){if(!demos.has(demoKey)){demos.set(demoKey,generateDemo(version.direction,sr));while(demos.size>2)demos.delete(demos.keys().next().value);}const demo=demos.get(demoKey);for(const track of version.tracks)if(!track.assetId)sources[track.id]=demo.tracks[track.kind];}for(const track of version.tracks)if(track.assetId)sources[track.id]=assets[track.assetId];const mix=renderMix(version,sources,sr),peaks=peaksFor(mix.left);self.postMessage({id,mix,peaks},[mix.left.buffer,mix.right.buffer]);}catch(error){self.postMessage({id:data.id,error:error.message});}};
